//! Read matrix of the simulated villains (`scripts/sim/profiles.json`) on
//! fixed-seed corpora of every format: cash 6-max, Zoom, MTT 9-max
//! knockout and Spin & Go. Each corpus is generated by
//! `scripts/sim/generate.mjs` into a temporary folder and imported into a
//! temporary database; for every profile player and every format he played,
//! the `strategic-analysis` build asks `EngineCache::payload` for his reads
//! in the between-hands context of his latest hand at his table, exactly as
//! the overlay does.
//!
//! The test prints a markdown matrix (chip tag, top-1 and top-2 reads,
//! payload timings, and the hit rate against the pro read oracle of
//! `docs/specs/opponent-engine.md`, section 16) and writes it to the path in
//! `VELORA_SIM_MATRIX_OUT` when that variable is set. In this task it
//! asserts structure only: every profile x format cell with hands yields a
//! payload, and every corpus and database path stays inside the temporary
//! folder.

use std::path::{Path, PathBuf};
use std::process::Command;

use rusqlite::Connection;
use serde_json::Value;
use velora_poker_lib::db;
use velora_poker_lib::engine::{load_hand, villain_context, EngineContext, StackBucket};
use velora_poker_lib::import::import_directory;

/// One corpus: generator format, seed, tables (tournaments at once) and
/// hands (per cash table, in total for Zoom, per seat for tournaments).
struct Corpus {
    format: &'static str,
    label: &'static str,
    seed: &'static str,
    tables: u32,
    hands: u32,
}

const CORPORA: [Corpus; 4] = [
    Corpus { format: "cash", label: "cash", seed: "matrix-cash", tables: 6, hands: 600 },
    Corpus { format: "zoom", label: "zoom", seed: "matrix-zoom", tables: 1, hands: 2500 },
    Corpus { format: "mtt", label: "mtt", seed: "matrix-mtt", tables: 4, hands: 400 },
    Corpus { format: "spin", label: "spin", seed: "matrix-spin", tables: 3, hands: 300 },
];

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("repo root").to_path_buf()
}

fn profiles() -> Value {
    let text = std::fs::read_to_string(repo_root().join("scripts/sim/profiles.json")).expect("read profiles.json");
    serde_json::from_str(&text).expect("profiles.json is JSON")
}

/// `path` resolves inside `root` (both canonicalised, so junctions and
/// `..` cannot leave it).
fn inside(root: &Path, path: &Path) -> bool {
    let root = std::fs::canonicalize(root).expect("canonical temp root");
    std::fs::canonicalize(path).is_ok_and(|p| p.starts_with(&root))
}

/// Runs the generator into `out` and returns its manifest.
fn generate(out: &Path, corpus: &Corpus) -> Value {
    let output = Command::new("node")
        .current_dir(repo_root())
        .arg("scripts/sim/generate.mjs")
        .args(["--out", out.to_str().expect("utf-8 path")])
        .args(["--format", corpus.format, "--seed", corpus.seed])
        .args(["--tables", &corpus.tables.to_string(), "--hands", &corpus.hands.to_string()])
        .args(["--pace", "0", "--manifest"])
        .output()
        .expect("run node scripts/sim/generate.mjs (is node on PATH?)");
    assert!(output.status.success(), "generator failed: {}", String::from_utf8_lossy(&output.stderr));
    serde_json::from_slice(&output.stdout).expect("manifest JSON")
}

/// Generates and imports one corpus under `root`; every file the generator
/// wrote and the database stay inside it.
fn build_corpus(root: &Path, corpus: &Corpus) -> Connection {
    let out = root.join(corpus.label).join("HandHistory");
    let manifest = generate(&out, corpus);
    assert!(inside(root, &out), "{}: hand histories outside the temporary folder", corpus.label);
    for table in manifest["tables"].as_array().expect("tables") {
        let file = out.join(table["file"].as_str().expect("file name"));
        assert!(inside(root, &file), "{}: {} outside the temporary folder", corpus.label, file.display());
    }
    let db_path = root.join(corpus.label).join("velora.db");
    let mut conn = db::open(&db_path).expect("open temp db");
    conn.execute_batch("PRAGMA synchronous = OFF;").expect("pragma");
    assert!(inside(root, &db_path), "{}: database outside the temporary folder", corpus.label);
    let summary = import_directory(&mut conn, &out).expect("import directory");
    assert_eq!(summary.hands_failed + summary.hands_rejected_invalid, 0, "{}: import failures", corpus.label);
    assert_eq!(summary.hands_imported as u64, manifest["hands"].as_u64().unwrap(), "{}: hands imported", corpus.label);
    conn
}

/// One villain in one format: his hands there and the between-hands
/// context of his latest hand at his latest table, the one after which he
/// is still seated (a hand he or the hero busted in closes that table for
/// the overlay).
struct Cell {
    profile: String,
    player: String,
    format: &'static str,
    hands: i64,
    context: Option<EngineContext>,
    #[cfg_attr(not(feature = "strategic-analysis"), allow(dead_code))]
    player_id: i64,
}

fn cells_of(conn: &Connection, corpus: &Corpus, profiles: &Value) -> Vec<Cell> {
    let mut cells = Vec::new();
    for profile in profiles["profiles"].as_array().expect("profiles") {
        for name in profile["players"].as_array().expect("players") {
            let name = name.as_str().expect("player name");
            let Ok(pid) = conn.query_row("SELECT id FROM players WHERE name = ?1", [name], |row| row.get::<_, i64>(0)) else {
                continue;
            };
            let ids: Vec<i64> = conn
                .prepare(
                    "SELECT h.id FROM hands h JOIN player_hands p ON p.hand_id = h.id
                      WHERE p.player_id = ?1 ORDER BY h.played_at DESC, h.id DESC",
                )
                .unwrap()
                .query_map([pid], |row| row.get(0))
                .unwrap()
                .collect::<Result<_, _>>()
                .unwrap();
            let context = ids.iter().find_map(|id| {
                let hand = load_hand(conn, *id).unwrap()?;
                villain_context(&hand, pid).filter(|c| c.effective_stack_bb.map_or(true, |eff| eff > 0.0))
            });
            cells.push(Cell {
                profile: profile["id"].as_str().unwrap().to_string(),
                player: name.to_string(),
                format: corpus.label,
                hands: ids.len() as i64,
                context,
                player_id: pid,
            });
        }
    }
    cells
}

/// `push_fold` at 15bb or less, else `deeper`; cash and Zoom are `any`.
fn depth_of(format: &str, context: Option<&EngineContext>) -> &'static str {
    if matches!(format, "cash" | "zoom") {
        return "any";
    }
    match context.and_then(|c| c.stack_bucket) {
        Some(StackBucket::PushFold) => "push_fold",
        _ => "deeper",
    }
}

fn context_label(context: Option<&EngineContext>) -> String {
    let Some(c) = context else { return "-".into() };
    let bucket = c.stack_bucket.map(|b| serde_json::to_value(b).unwrap().as_str().unwrap().to_string());
    let stage = c.stage.map(|s| serde_json::to_value(s).unwrap().as_str().unwrap().to_string());
    let mut parts = vec![format!("{}bb {}", c.effective_stack_bb.map_or("?".into(), |e| format!("{e:.1}")), bucket.unwrap_or_default())];
    if let Some(stage) = stage {
        parts.push(stage);
    }
    if let Some(bounty) = &c.bounty {
        parts.push(format!("KO x{:.1}", bounty.ratio.unwrap_or(0.0)));
    }
    if let Some(seat) = &c.seat {
        parts.push(format!("{}{}", if seat.side == velora_poker_lib::engine::Side::Left { "L" } else { "R" }, seat.distance));
    }
    parts.join(", ")
}

// ------------------------------------------------------------ oracle (section 16)

/// One oracle row: the reads a winning pro accepts as top-1, and the ones
/// he also accepts in the top two, for one profile, format and depth.
#[derive(Debug)]
struct OracleRow {
    profile: String,
    format: String,
    depth: String,
    top1: Vec<String>,
    top2: Vec<String>,
}

const ORACLE_START: &str = "<!-- oracle:start -->";
const ORACLE_END: &str = "<!-- oracle:end -->";

fn ticked(cell: &str) -> Vec<String> {
    cell.split('`').skip(1).step_by(2).map(|s| s.trim().to_string()).collect()
}

/// The oracle table of `docs/specs/opponent-engine.md`, section 16, or
/// `None` on a checkout without the spec: docs/ is local-only (git-excluded),
/// so the oracle checks are skipped there, as in engine_rules_tests.
fn oracle() -> Option<Vec<OracleRow>> {
    let spec_path = repo_root().join("docs/specs/opponent-engine.md");
    let Ok(spec) = std::fs::read_to_string(&spec_path) else {
        eprintln!("skipping oracle checks: {} is not present", spec_path.display());
        return None;
    };
    let (Some(start), Some(end)) = (spec.find(ORACLE_START), spec.find(ORACLE_END)) else {
        return Some(Vec::new());
    };
    let rows = spec[start + ORACLE_START.len()..end]
        .lines()
        .map(str::trim)
        .filter(|l| l.starts_with('|') && !l.starts_with("|---") && !l.starts_with("| Profile"))
        .map(|line| {
            let cells: Vec<&str> = line.trim_matches('|').split('|').map(str::trim).collect();
            assert!(cells.len() >= 5, "oracle row with too few cells: {line}");
            OracleRow {
                profile: cells[0].trim_matches('`').to_string(),
                format: cells[1].trim_matches('`').to_string(),
                depth: cells[2].trim_matches('`').to_string(),
                top1: ticked(cells[3]),
                top2: ticked(cells[4]),
            }
        })
        .collect();
    Some(rows)
}

fn oracle_row<'a>(oracle: &'a [OracleRow], profile: &str, format: &str, depth: &str) -> Option<&'a OracleRow> {
    oracle.iter().find(|r| r.profile == profile && r.format == format && (r.depth == depth || r.depth == "any"))
}

// ------------------------------------------------------------ engine (strategic-analysis)

/// What the matrix shows of one payload.
#[derive(Debug, Default, Clone)]
struct Seen {
    chip: Option<String>,
    /// Tendency reads in ranking order, context facts left out: `(rule id, tag, score)`.
    reads: Vec<(String, Option<String>, f64)>,
    /// Context facts ranked above the first tendency read.
    facts: Vec<String>,
    cold_ms: f64,
    warm_ms: f64,
}

/// A fact of the latest hand rather than a read of the player
/// (section 7): stack depth and his bounty.
#[allow(dead_code)]
fn is_fact(rule_id: &str) -> bool {
    rule_id.starts_with("ctx.") || rule_id == "ko.big_bounty"
}

#[cfg(feature = "strategic-analysis")]
fn payloads(conn: &Connection, cells: &[Cell]) -> Vec<Option<Seen>> {
    use std::time::Instant;
    use velora_poker_lib::engine::EngineCache;
    let mut cache = EngineCache::new();
    // Warm the pool priors once, so a villain's first payload times his own
    // replay rather than the pool walk over the whole corpus.
    cache.pool().tally(conn).expect("pool tally");
    cells
        .iter()
        .map(|cell| {
            if cell.hands == 0 {
                return None;
            }
            let started = Instant::now();
            let payload = cache.payload(conn, cell.player_id, cell.context.clone()).expect("engine payload");
            let cold_ms = started.elapsed().as_secs_f64() * 1000.0;
            let started = Instant::now();
            let again = cache.payload(conn, cell.player_id, cell.context.clone()).expect("engine payload");
            let warm_ms = started.elapsed().as_secs_f64() * 1000.0;
            assert_eq!(payload.reads.len(), again.reads.len(), "{}: a cached payload differs", cell.player);
            let first_read = payload.reads.iter().position(|r| !is_fact(&r.rule_id)).unwrap_or(payload.reads.len());
            Some(Seen {
                chip: payload.tag.as_ref().map(|t| t.text.clone()),
                reads: payload
                    .reads
                    .iter()
                    .filter(|r| !is_fact(&r.rule_id))
                    .map(|r| (r.rule_id.clone(), r.tag.clone(), r.score))
                    .collect(),
                facts: payload.reads[..first_read].iter().map(|r| r.rule_id.clone()).collect(),
                cold_ms,
                warm_ms,
            })
        })
        .collect()
}

#[cfg(not(feature = "strategic-analysis"))]
fn payloads(_conn: &Connection, cells: &[Cell]) -> Vec<Option<Seen>> {
    cells.iter().map(|_| None).collect()
}

// ------------------------------------------------------------ report

fn read_label(read: Option<&(String, Option<String>, f64)>) -> String {
    match read {
        Some((id, tag, score)) => format!("`{id}` {} {score:.2}", tag.as_deref().unwrap_or("—")),
        None => "(none)".into(),
    }
}

fn percentile(values: &[f64], p: f64) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let rank = ((p / 100.0) * sorted.len() as f64).ceil() as usize;
    sorted[rank.clamp(1, sorted.len()) - 1]
}

/// Top-1 hit: the first tendency read (or `(none)` when there is none) is in
/// the cell's top-1 set. Top-2 hit: each of the first two tendency reads is
/// in the accepted set (top-1 set, top-2 set, and any `sd.*` read); no read
/// at all counts only when `(none)` is an accepted top-1.
fn hits(row: &OracleRow, seen: &Seen) -> (bool, bool) {
    let first = seen.reads.first().map_or("(none)", |r| r.0.as_str());
    let top1 = row.top1.iter().any(|id| id == first);
    let accepted = |id: &str| id.starts_with("sd.") || row.top1.iter().chain(&row.top2).any(|a| a == id);
    let top2 = if seen.reads.is_empty() { top1 } else { seen.reads.iter().take(2).all(|r| accepted(&r.0)) };
    (top1, top2)
}

fn report(cells: &[Cell], seen: &[Option<Seen>], oracle: &[OracleRow]) -> String {
    let mut md = String::new();
    md += "| Profile | Player | Format | Hands | Context | Chip | Top-1 | Top-2 | Facts above | Oracle top-1 | Oracle top-2 | Cold ms | Warm ms |\n";
    md += "|---|---|---|---|---|---|---|---|---|---|---|---|---|\n";
    let mut tally: Vec<(&str, u32, u32, u32)> = Vec::new();
    for (cell, seen) in cells.iter().zip(seen) {
        let depth = depth_of(cell.format, cell.context.as_ref());
        let row = oracle_row(oracle, &cell.profile, cell.format, depth);
        let (chip, top1, top2, facts, o1, o2, cold, warm) = match seen {
            Some(s) => {
                let (h1, h2) = row.map_or((false, false), |r| hits(r, s));
                if row.is_some() {
                    let slot = match tally.iter().position(|t| t.0 == cell.format) {
                        Some(i) => i,
                        None => {
                            tally.push((cell.format, 0, 0, 0));
                            tally.len() - 1
                        }
                    };
                    tally[slot].1 += 1;
                    tally[slot].2 += h1 as u32;
                    tally[slot].3 += h2 as u32;
                }
                let mark = |hit: bool| if row.is_none() { "no oracle" } else if hit { "hit" } else { "miss" };
                (
                    s.chip.clone().unwrap_or_else(|| "—".into()),
                    read_label(s.reads.first()),
                    read_label(s.reads.get(1)),
                    if s.facts.is_empty() { "—".into() } else { s.facts.join(", ") },
                    mark(h1),
                    mark(h2),
                    format!("{:.1}", s.cold_ms),
                    format!("{:.2}", s.warm_ms),
                )
            }
            None => ("n/a".into(), "n/a".into(), "n/a".into(), "n/a".into(), "-", "-", "-".into(), "-".into()),
        };
        md += &format!(
            "| {} | {} | {} | {} | {} | {chip} | {top1} | {top2} | {facts} | {o1} | {o2} | {cold} | {warm} |\n",
            cell.profile,
            cell.player,
            if depth == "any" { cell.format.to_string() } else { format!("{} ({depth})", cell.format) },
            cell.hands,
            context_label(cell.context.as_ref()),
        );
    }
    if !tally.is_empty() {
        md += "\n| Format | Cells | Top-1 hits | Top-2 hits |\n|---|---|---|---|\n";
        let (mut n, mut h1, mut h2) = (0, 0, 0);
        for (format, cells, t1, t2) in &tally {
            md += &format!("| {format} | {cells} | {t1} | {t2} |\n");
            n += cells;
            h1 += t1;
            h2 += t2;
        }
        let pct = |h: u32| if n == 0 { 0.0 } else { 100.0 * h as f64 / n as f64 };
        md += &format!("| all | {n} | {h1} ({:.0}%) | {h2} ({:.0}%) |\n", pct(h1), pct(h2));
    }
    let timed: Vec<&Seen> = seen.iter().flatten().collect();
    if !timed.is_empty() {
        let cold: Vec<f64> = timed.iter().map(|s| s.cold_ms).collect();
        let warm: Vec<f64> = timed.iter().map(|s| s.warm_ms).collect();
        md += &format!(
            "\nPayload time per villain over {} cells ({} build): first payload (his replay) median {:.1} ms, p95 {:.1} ms; cached refresh median {:.2} ms, p95 {:.2} ms.\n",
            timed.len(),
            if cfg!(debug_assertions) { "debug" } else { "release" },
            percentile(&cold, 50.0),
            percentile(&cold, 95.0),
            percentile(&warm, 50.0),
            percentile(&warm, 95.0),
        );
    }
    md
}

/// Where the matrix may be written: an explicit file, never inside the
/// real Velora data folder or a PokerStars folder.
fn matrix_out() -> Option<PathBuf> {
    let path = PathBuf::from(std::env::var_os("VELORA_SIM_MATRIX_OUT")?);
    let lower = path.to_string_lossy().to_lowercase().replace('/', "\\");
    assert!(!lower.contains("com.velora.poker"), "VELORA_SIM_MATRIX_OUT points into the Velora data folder");
    assert!(!lower.contains("pokerstars"), "VELORA_SIM_MATRIX_OUT points into a PokerStars folder");
    Some(path)
}

/// The oracle names only real rule ids (or `(none)` as a top-1) and has
/// exactly one row per profile, format and depth.
#[test]
fn pro_oracle_covers_every_profile_and_format_with_real_rule_ids() {
    use velora_poker_lib::engine::RULES;
    let Some(oracle) = oracle() else { return };
    assert!(!oracle.is_empty(), "no oracle table between {ORACLE_START} and {ORACLE_END}");
    for row in &oracle {
        assert!(!row.top1.is_empty(), "{} {} {}: empty top-1 set", row.profile, row.format, row.depth);
        for id in row.top1.iter().chain(&row.top2) {
            let real = RULES.iter().any(|r| r.id == id) || (id == "(none)" && row.top1.contains(id));
            assert!(real, "{} {} {}: unknown rule id {id}", row.profile, row.format, row.depth);
            assert!(!is_fact(id), "{} {} {}: {id} is a context fact, not a read", row.profile, row.format, row.depth);
        }
    }
    for profile in profiles()["profiles"].as_array().unwrap() {
        let id = profile["id"].as_str().unwrap();
        for corpus in &CORPORA {
            let depths: &[&str] = if matches!(corpus.label, "cash" | "zoom") { &["any"] } else { &["push_fold", "deeper"] };
            for depth in depths {
                let rows = oracle.iter().filter(|r| r.profile == id && r.format == corpus.label && r.depth == *depth).count();
                assert_eq!(rows, 1, "oracle rows for {id} {} {depth}", corpus.label);
            }
        }
    }
}

#[test]
fn simulated_villains_read_matrix_covers_every_profile_and_format() {
    let tmp = tempfile::tempdir().expect("temp dir");
    let root = tmp.path();
    if let Some(appdata) = std::env::var_os("APPDATA") {
        let real = PathBuf::from(appdata).join("com.velora.poker");
        assert!(!root.starts_with(&real), "the temporary folder is inside the real Velora data folder");
    }
    let profiles = profiles();
    let oracle = oracle().unwrap_or_default();
    let mut cells = Vec::new();
    let mut seen = Vec::new();
    for corpus in &CORPORA {
        let conn = build_corpus(root, corpus);
        let format_cells = cells_of(&conn, corpus, &profiles);
        let format_seen = payloads(&conn, &format_cells);
        for cell in &format_cells {
            if cell.hands > 0 {
                assert!(cell.context.is_some(), "{} {}: no between-hands context", cell.format, cell.player);
            }
        }
        cells.extend(format_cells);
        seen.extend(format_seen);
        drop(conn);
    }

    // Every profile played every format.
    for profile in profiles["profiles"].as_array().unwrap() {
        let id = profile["id"].as_str().unwrap();
        for corpus in &CORPORA {
            let played = cells.iter().any(|c| c.profile == id && c.format == corpus.label && c.hands > 0);
            assert!(played, "profile {id} has no hands in the {} corpus", corpus.label);
        }
    }
    // Strategic-analysis build: every cell with hands yields a payload.
    if cfg!(feature = "strategic-analysis") {
        for (cell, seen) in cells.iter().zip(&seen) {
            assert_eq!(cell.hands > 0, seen.is_some(), "{} {}: payload", cell.format, cell.player);
        }
    }

    let md = report(&cells, &seen, &oracle);
    println!("{md}");
    if let Some(path) = matrix_out() {
        std::fs::write(&path, &md).expect("write VELORA_SIM_MATRIX_OUT");
    }
}
